const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2021 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.navigator {\n  min-height: 24px;\n  display: flex;\n  flex-wrap: nowrap;\n  justify-content: space-between;\n  overflow: hidden;\n  align-items: center;\n  background-color: var(--color-background);\n  color: var(--color-text-primary);\n}\n\n.navigator-item {\n  display: flex;\n  white-space: nowrap;\n  overflow: hidden;\n}\n\n.address-input {\n  text-align: center;\n  outline: none;\n  color: var(--color-text-primary);\n  border: 1px solid var(--color-background-elevation-2);\n  background: transparent;\n}\n\n.address-input.invalid {\n  color: var(--color-accent-red);\n}\n\n.navigator-button {\n  display: flex;\n  width: 20px;\n  height: 20px;\n  background: transparent;\n  overflow: hidden;\n  border: none;\n  padding: 0;\n  outline: none;\n  justify-content: center;\n  align-items: center;\n  cursor: pointer;\n}\n\n.navigator-button:disabled devtools-icon {\n  opacity: 50%;\n}\n\n.navigator-button:enabled:hover devtools-icon {\n  --icon-color: var(--icon-default-hover);\n}\n\n.navigator-button:enabled:focus devtools-icon {\n  --icon-color: var(--icon-default-hover);\n}\n\n/*# sourceURL=linearMemoryNavigator.css */\n");export default styles;